package com.foundgine.providers.storage.postgresvector;
import com.foundgine.core.semantic.*;import com.foundgine.core.semantic.resolution.*;import java.sql.*;import java.util.*;import javax.sql.DataSource;
/** Maintains the derived pgvector semantic lexicon projection. */
public final class PgVectorSemanticLexiconIndexClient {private final DataSource ds;private final PgVectorSemanticLexicalCandidateSource.EmbeddingGenerator embeddings;private final PgVectorOptions options;public PgVectorSemanticLexiconIndexClient(DataSource d,PgVectorSemanticLexicalCandidateSource.EmbeddingGenerator e,PgVectorOptions o){ds=Objects.requireNonNull(d);embeddings=Objects.requireNonNull(e);options=Objects.requireNonNull(o);}public void ensureSchema(){String t=options.qualifiedTableName();try(Connection c=ds.getConnection();Statement s=c.createStatement()){s.execute("CREATE EXTENSION IF NOT EXISTS vector");s.execute("CREATE TABLE IF NOT EXISTS "+t+" (id bigserial primary key,canonical_name text not null,kind text not null,search_text text not null,aliases text[] not null default ARRAY[]::text[],description text,entity_id bigint,relationship_id bigint,field_id bigint,source_entity_id bigint,target_entity_id bigint,value text,embedding vector("+options.dimensions()+"))");}catch(SQLException e){throw new IllegalStateException("Unable to create pgvector lexicon",e);}}public void indexContract(SemanticContractSnapshot contract){ensureSchema();List<SemanticLexiconEntry> es=SemanticLexiconProjection.build(contract);try(Connection c=ds.getConnection()){c.setAutoCommit(false);try(Statement s=c.createStatement()){s.executeUpdate("TRUNCATE "+options.qualifiedTableName());}for(var e:es)insert(c,e);c.commit();}catch(SQLException e){throw new IllegalStateException("Unable to index pgvector lexicon",e);}}private void insert(Connection c,SemanticLexiconEntry e)throws SQLException{float[] v=embeddings.embed(e.searchText());String sql="INSERT INTO "+options.qualifiedTableName()+"(canonical_name,kind,search_text,description,entity_id,relationship_id,field_id,source_entity_id,target_entity_id,value,embedding) VALUES(?,?,?,?,?,?,?,?,?,?,?)";try(PreparedStatement p=c.prepareStatement(sql)){p.setString(1,e.canonicalName());p.setString(2,e.kind().toString());p.setString(3,e.searchText());p.setString(4,e.description());p.setObject(5,e.entityId()==null?null:e.entityId().value());p.setObject(6,e.relationshipId()==null?null:e.relationshipId().value());p.setObject(7,e.fieldId()==null?null:e.fieldId().value());p.setObject(8,e.sourceEntityId()==null?null:e.sourceEntityId().value());p.setObject(9,e.targetEntityId()==null?null:e.targetEntityId().value());p.setString(10,e.value());p.setString(11,Arrays.toString(v));p.executeUpdate();}}}
